with flattened_attrs as (select id, service, host, log_ts, level, context, coalesce(context['region'], 'unknown') as region_or_default, context['trace'] as trace, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, get_json_object(payload_json, '$.user.tier') as user_tier from app_logs where level in ('WARN', 'DEBUG')) select host, count(distinct trace) as distinct_traces, percentile_approx(retry_count, 0.9) as retry_count_p90, min(log_ts) as started_at from flattened_attrs group by host order by distinct_traces desc nulls first
